/**
 * A generic decoder for Bluetooth GATT characteristic values, driven by the
 * Bluetooth SIG's GATT Specification Supplement (gss) structures as
 * src/data/bluetoothGatt.ts holds them (generated by
 * scripts/fetch-bluetooth-gatt.mjs from the SIG's public repository; never
 * hand-edited).
 *
 * Behind /tools/ftms-lab, /tools/cycling-power-lab and
 * /tools/ble-gatt-explorer. One plain-ESM module with no dependencies and no
 * network call, imported by those pages' client components and by
 * scripts/gatt-decode.test.mjs, so the tests run exactly the code a reader
 * runs.
 *
 * It knows no characteristic. `compileLayout` turns one characteristic record
 * into a plain-JSON layout:
 *
 *   - field order, gss types and sizes        ← `gss.structure`
 *   - which flags bit makes a field present   ← the field's parsed
 *                                               "Present if bit N of <Flags>
 *                                               field is set to V" line
 *   - what each flags / feature bit means     ← the field's `bits` definition
 *   - struct members (wheel and crank data…)  ← the struct definition's layout
 *   - value tables (Sensor Location…)         ← the field's `values` definition
 *   - units                                   ← each field's `units`
 *   - resolution                              ← the field's own
 *                                               "Represented values: M = …,
 *                                               d = …, b = …" line, kept as
 *                                               evidence with the "Unit is …"
 *                                               line beside it
 *
 * The resolution is read as M × 10^d × 2^b. The SIG's lines do not spell that
 * formula out, but every "Represented values" line in the dataset sits next to
 * a "Unit is …" sentence, and scripts/gatt-decode.test.mjs checks the product
 * against each one it can parse (1/1024 second for b = -10, 0.005 kilogram for
 * M = 5, d = -3…). Where the two disagree in the SIG's own text (Resistance
 * Level: d = 1 beside "Unit is 1") the layout carries both and the page shows
 * both; nothing is silently picked.
 *
 * What the structure does not describe in a form this module understands —
 * medfloat16/medfloat32 (whose encoding is not in the SIG's YAML files), a
 * condition that is not one "Present if bit N" line, a field "Determined by
 * UUID" — is marked unsupported: decoding stops there and the remaining
 * octets are shown raw. Nothing is guessed.
 *
 * Byte order is not in the SIG's YAML either; multi-octet fields are read
 * little-endian, as the Web Bluetooth specification's own heart-rate example
 * does (BYTE_ORDER_SOURCE, shared with /tools/heart-rate-lab).
 */
import { BYTE_ORDER_SOURCE, parseHex, toBytes, toHex } from "./hrMeasurement.mjs";

export { BYTE_ORDER_SOURCE, parseHex, toBytes, toHex };

/* ---------------------------------------------------------------------- *
 * Reading the SIG's text
 * ---------------------------------------------------------------------- */

const INT = /^(u|s)?int(4|8|12|16|24|32)$/;
const ARRAY = /^(u|s)int(8|16|24|32)\s*\[(n|\d+\s*[–-]\s*\d+)\]$/;
const BOOL = /^boolean\[(8|16|24|32)\]$/;
const REP = /Represented values:\s*M\s*=\s*(-?\d+),\s*d\s*=\s*(-?\d+),\s*b\s*=\s*(-?\d+)/;

/** "0" → [0]; "5–7" (en dash or hyphen) → [5, 6, 7]. */
function bitList(s) {
  const t = String(s).trim();
  const m = /^(\d+)\s*[–-]\s*(\d+)$/.exec(t);
  if (m) {
    const out = [];
    for (let i = Number(m[1]); i <= Number(m[2]); i++) out.push(i);
    return out;
  }
  if (/^\d+$/.test(t)) return [Number(t)];
  return null;
}

/** "0x07–0xFF" / "17–255" / "3" → {from, to}; null for anything else. */
function valueRange(s) {
  const num = (x) => (/^0x[0-9a-f]+$/i.test(x) ? parseInt(x, 16) : /^\d+$/.test(x) ? Number(x) : NaN);
  const [a, b] = String(s).trim().split(/\s*[–-]\s*/);
  const from = num(a);
  const to = b === undefined ? from : num(b);
  return Number.isFinite(from) && Number.isFinite(to) ? { from, to } : null;
}

/** The resolution a "Unit is …" sentence states, where it states one as a number. */
export function unitIsFactor(line) {
  if (!line) return null;
  let m = /\b1\/(\d+)/.exec(line);
  if (m) return 1 / Number(m[1]);
  m = /resolution of (\d+(?:\.\d+)?)/.exec(line);
  if (m) return Number(m[1]);
  m = /^Unit is (\d+(?:\.\d+)?)(?![\d/])/.exec(line);
  if (m) return Number(m[1]);
  m = /^Unit is [A-Za-z]+ with (\d+(?:\.\d+)?)/.exec(line);
  if (m) return Number(m[1]);
  return null;
}

const close = (a, b) => Math.abs(a - b) <= 1e-9 * Math.max(Math.abs(a), Math.abs(b));

/**
 * The scale a field's text gives, or null when it gives none.
 * factor = M × 10^d × 2^b; `unitIs` is the "Unit is" line beside it, verbatim,
 * and `conflict` is true when that line states a different number.
 */
export function readScale(text) {
  if (!text) return null;
  const lines = String(text).split("\n").map((l) => l.trim());
  const repLine = lines.find((l) => REP.test(l));
  if (!repLine) return null;
  const m = REP.exec(repLine);
  const M = Number(m[1]);
  const d = Number(m[2]);
  const b = Number(m[3]);
  const factor = M * 10 ** d * 2 ** b;
  const unitIs = lines.find((l) => /^Unit is\b/.test(l)) ?? null;
  const stated = unitIsFactor(unitIs);
  return {
    M,
    d,
    b,
    factor: Number(factor.toPrecision(12)),
    evidence: repLine.replace(/\.$/, ""),
    unitIs,
    unitIsFactor: stated,
    conflict: stated != null && !close(stated, factor),
  };
}

/** "velocity (kilometre per hour)" → "kilometre per hour"; the id's tail when units.yaml has no name. */
function unitLabel(u) {
  if (!u) return null;
  if (u.id.endsWith("unitless")) return "";
  if (u.name) {
    const m = /\(([^)]+)\)$/.exec(u.name);
    return m ? m[1] : u.name;
  }
  return u.id.split(".").pop().replace(/_/g, " ");
}

const unitOf = (units) => (units?.[0] ? { id: units[0].id, label: unitLabel(units[0]), evidence: units[0].evidence } : null);

/** The definition a field's "See \autoref{sec:<id>/field/<key>}" points at, else one with the same name. */
function definitionFor(c, f, kind) {
  const defs = [];
  const walk = (ds) => ds.forEach((d) => (defs.push(d), walk(d.subfields ?? [])));
  walk(c.gss?.definitions ?? []);
  const ref = /\\autoref\{sec:[^}/]+\/field\/([^}]+)\}/.exec(f.description ?? "");
  const byKey = ref ? defs.find((d) => d.key === ref[1] && (!kind || d.kind === kind)) : null;
  return byKey ?? defs.find((d) => d.name.toLowerCase() === f.name.toLowerCase() && (!kind || d.kind === kind)) ?? null;
}

function compileBits(def) {
  if (!def) return null;
  return def.rows.map((r) => ({
    bits: bitList(r.bit) ?? [],
    label: r.bit,
    description: r.description,
    reserved: /Reserved for Future Use/i.test(r.description),
  }));
}

function compileValues(def) {
  if (!def) return null;
  const rows = def.rows
    .map((r) => {
      const range = valueRange(r.value);
      return range ? { ...range, value: r.value, description: r.description } : null;
    })
    .filter(Boolean);
  return rows.length ? rows : null;
}

/* ---------------------------------------------------------------------- *
 * Compiling
 * ---------------------------------------------------------------------- */

function compileStruct(c, f, def) {
  if (!def || def.kind !== "struct" || !def.layout?.length) return { reason: `no struct definition for ${f.name} in the SIG's file` };
  const packed = !!def.sizeInBits;
  const children = [];
  let bitOffset = 0;
  for (const r of def.layout) {
    const m = INT.exec(r.type);
    const bm = BOOL.exec(r.type);
    if ((!m && !bm) || r.presence || r.sizeKind !== "fixed" || r.sizeN == null) {
      return { reason: `${f.name} › ${r.name}: ${r.type} (${r.size}) is not a fixed-size integer this decoder reads` };
    }
    const bitsWide = packed ? r.sizeN : r.sizeN * 8;
    if (!packed && bitsWide !== Number(m ? m[2] : bm[1])) return { reason: `${f.name} › ${r.name}: size ${r.size} does not match ${r.type}` };
    children.push({
      name: r.name,
      anchor: r.anchor,
      type: r.type,
      kind: bm ? "bits" : m[1] === "u" ? "uint" : "sint",
      bitWidth: bitsWide,
      bitOffset,
      unit: unitOf(r.units),
      scale: readScale(def.rows.find((x) => x.field === r.name)?.description),
    });
    bitOffset += bitsWide;
  }
  const width = f.sizeN;
  if (width == null || bitOffset !== width * 8) return { reason: `${f.name}: members add up to ${bitOffset} bits, the field is ${f.size} octets` };
  return { children, packed, width, description: packed || def.referenced ? def.description : null };
}

/**
 * A struct field whose text says "Refer to Date Time characteristic in
 * \autoref{sec:org.bluetooth.characteristic.date_time}" takes that
 * characteristic's structure as its members, when `resolve` can find it.
 * Shaped like a struct definition so compileStruct reads both the same way.
 */
function referencedStructure(f, resolve) {
  if (!resolve) return null;
  const ref = /\\autoref\{sec:(org\.bluetooth\.characteristic\.[a-z0-9_]+)\}/.exec(f.description ?? "");
  const other = ref ? resolve(ref[1]) : null;
  if (!other?.gss?.structure?.length) return null;
  return {
    kind: "struct",
    sizeInBits: false,
    referenced: true,
    description: `Members from ${other.name} (${other.uuid}), which the field's text refers to.`,
    layout: other.gss.structure,
    rows: other.gss.structure.map((x) => ({ field: x.name, description: x.description ?? "" })),
  };
}

/**
 * Compile one characteristic record from src/data/bluetoothGatt.ts into the
 * layout `decode` and `encode` use. Pure; the result is plain JSON, so a
 * server component can hand it to a client one without shipping the 600 KB
 * data module. `resolve(id)` (optional) returns another characteristic record,
 * for struct fields that refer to one (Time Stamp → Date Time).
 */
export function compileLayout(c, resolve = null) {
  if (!c) throw new Error("compileLayout: no characteristic");
  const base = {
    uuid: c.uuid,
    uuidNumber: parseInt(c.uuid, 16),
    id: c.id,
    name: c.name,
    slug: c.slug,
    hasPage: !!c.hasPage,
    file: c.gss?.file ?? null,
    byteOrder: "little-endian",
  };
  if (!c.gss?.structure?.length) return { ...base, fields: [], unsupported: "The SIG's public repository has no gss structure for this characteristic." };

  let unsupported = null;
  const fields = c.gss.structure.map((f) => {
    const out = {
      name: f.name,
      anchor: f.anchor,
      type: f.type,
      size: f.size,
      sizeKind: f.sizeKind,
      kind: "unsupported",
      width: null,
      presence: f.presence ? { field: f.presence.field, bit: f.presence.bit, value: f.presence.value, evidence: f.presence.evidence } : null,
      presenceText: f.presenceText,
      unit: unitOf(f.units),
      scale: readScale(f.description),
      bits: null,
      values: null,
      children: null,
      packed: false,
      structNote: null,
      // Where the SIG states a field's meaning only in prose (Weight
      // Measurement's Weight: "in kilograms with resolution 0.005 if the bit
      // 0 of the Flag field is 0 or in pounds…"), its text travels with the
      // field so the reader sees it beside the raw value instead of a guess.
      prose:
        !readScale(f.description) && !f.units?.length && f.description && !/^See \\autoref/.test(f.description)
          ? f.description
              .split("\n")
              .filter((l) => !/^Present if/.test(l.trim()))
              .join(" ")
              .trim() || null
          : null,
      reason: null,
    };
    // A condition other than one parsed "Present if bit N" line, on a field
    // that is not always there, cannot be evaluated from the value alone.
    if (!f.presence && f.sizeKind !== "fixed" && f.presenceText) {
      out.reason = `its condition is not a flags bit: "${f.presenceText}"`;
    } else if (BOOL.test(f.type)) {
      out.kind = "bits";
      out.width = Number(BOOL.exec(f.type)[1]) / 8;
      out.bits = compileBits(definitionFor(c, f, "bits"));
    } else if (INT.test(f.type) && Number(INT.exec(f.type)[2]) % 8 === 0) {
      const m = INT.exec(f.type);
      // "uint16" is unsigned; "sint16" and the one bare "int16" are signed.
      out.kind = m[1] === "u" ? "uint" : "sint";
      out.width = Number(m[2]) / 8;
      out.values = compileValues(definitionFor(c, f, "values"));
    } else if (ARRAY.test(f.type)) {
      const m = ARRAY.exec(f.type);
      out.kind = "array";
      out.signed = m[1] === "s";
      out.width = Number(m[2]) / 8;
    } else if (f.type === "utf8s") {
      out.kind = "utf8";
    } else if (f.type === "struct") {
      const s = compileStruct(c, f, definitionFor(c, f, "struct") ?? referencedStructure(f, resolve));
      if (s.reason) out.reason = s.reason;
      else {
        out.kind = "struct";
        out.width = s.width;
        out.children = s.children;
        out.packed = s.packed;
        out.structNote = s.description;
      }
    } else {
      out.reason = `${f.type} is not decoded here: the SIG's YAML files do not define its encoding`;
    }
    if (out.kind === "unsupported" && !unsupported) unsupported = `${f.name}: ${out.reason}`;
    return out;
  });
  return { ...base, fields, unsupported };
}

/* ---------------------------------------------------------------------- *
 * Bytes
 * ---------------------------------------------------------------------- */

function readUint(bytes, off, width) {
  let v = 0;
  for (let i = width - 1; i >= 0; i--) v = v * 256 + bytes[off + i];
  return v;
}

function toSigned(v, bits) {
  const half = 2 ** (bits - 1);
  return v >= half ? v - 2 ** bits : v;
}

function writeUint(out, v, width) {
  let x = v < 0 ? v + 2 ** (width * 8) : v;
  for (let i = 0; i < width; i++) {
    out.push(x % 256);
    x = Math.floor(x / 256);
  }
}

const bitOf = (v, i) => Math.floor(v / 2 ** i) % 2;

/** "12.5", "0.01", "-3"; up to six decimals, trailing zeros dropped. */
export function fmt(n) {
  if (n == null || !Number.isFinite(n)) return "—";
  return String(Number(n.toFixed(6)));
}

function scaled(raw, scale) {
  return scale ? Number((raw * scale.factor).toPrecision(12)) : raw;
}

function displayOf(value, unit) {
  const u = unit?.label;
  return u ? `${fmt(value)} ${u}` : fmt(value);
}

/* ---------------------------------------------------------------------- *
 * Decoding
 * ---------------------------------------------------------------------- */

function decodeBits(v, rows) {
  if (!rows) return null;
  return rows.map((r) => {
    const values = r.bits.map((i) => bitOf(v, i));
    // A multi-bit row (20–21) is a little-endian number over its bits.
    const n = values.reduce((acc, b, i) => acc + b * 2 ** i, 0);
    return { label: r.label, description: r.description, reserved: r.reserved, values, value: n, set: values.some(Boolean) };
  });
}

/**
 * Decode one characteristic value against a compiled layout.
 *
 * Returns every field (present, absent or unknown, with the condition that
 * decided it), byte spans for highlighting, and the problems found. Problems
 * are reported in `errors`, never thrown: this runs on whatever a device sends.
 */
export function decode(input, layout) {
  const bytes = toBytes(input);
  const out = { hex: toHex(bytes), length: bytes.length, fields: [], spans: [], errors: [], trailing: 0, stopped: null };
  if (!layout.fields.length) {
    out.stopped = layout.unsupported;
    if (bytes.length) out.spans.push({ start: 0, end: bytes.length, field: -1, label: "No structure to decode against" });
    return out;
  }
  const flags = new Map();
  let off = 0;
  let stopped = null;
  const laterPresent = (i) =>
    layout.fields.slice(i + 1).some((g) => (g.presence && flags.has(g.presence.field) ? bitOf(flags.get(g.presence.field), g.presence.bit) === g.presence.value : !g.presence && g.sizeKind === "fixed"));

  layout.fields.forEach((f, i) => {
    const base = { name: f.name, anchor: f.anchor, type: f.type, unit: f.unit, scale: f.scale, presence: f.presence, offset: null, length: 0, raw: null, value: null, display: null, bits: null, children: null, valueLabel: null, note: null };
    if (stopped) {
      out.fields.push({ ...base, status: "unknown" });
      return;
    }
    let present = true;
    if (f.presence) {
      if (!flags.has(f.presence.field)) {
        stopped = `${f.name}: its condition names ${f.presence.field}, which was not decoded before it`;
        out.fields.push({ ...base, status: "unknown" });
        return;
      }
      present = bitOf(flags.get(f.presence.field), f.presence.bit) === f.presence.value;
    }
    if (!present) {
      out.fields.push({ ...base, status: "absent" });
      return;
    }
    if (f.kind === "unsupported") {
      stopped = `${f.name}: ${f.reason}`;
      out.fields.push({ ...base, status: "unknown", offset: off, note: f.reason });
      return;
    }
    // Variable-length fields take what is left, but only when nothing after
    // them is present: otherwise where they end cannot be known.
    if (f.kind === "utf8" || f.kind === "array") {
      if (laterPresent(i)) {
        stopped = `${f.name} has no stated length and a later field is present, so where it ends cannot be read from the value`;
        out.fields.push({ ...base, status: "unknown", offset: off });
        return;
      }
      const rest = bytes.length - off;
      if (f.kind === "utf8") {
        const slice = bytes.subarray(off, bytes.length);
        let text = null;
        try {
          text = new TextDecoder("utf-8", { fatal: true }).decode(slice);
        } catch {
          out.errors.push(`${f.name} is not valid UTF-8.`);
        }
        out.fields.push({ ...base, status: "present", offset: off, length: rest, raw: text, value: text, display: text == null ? null : JSON.stringify(text) });
        if (rest) out.spans.push({ start: off, end: bytes.length, field: i, label: f.name });
        off = bytes.length;
        return;
      }
      const n = Math.floor(rest / f.width);
      const raw = [];
      for (let k = 0; k < n; k++) {
        const s = off + k * f.width;
        const v = readUint(bytes, s, f.width);
        raw.push(f.signed ? toSigned(v, f.width * 8) : v);
        out.spans.push({ start: s, end: s + f.width, field: i, label: `${f.name} [${k}]` });
      }
      const value = raw.map((v) => scaled(v, f.scale));
      out.fields.push({ ...base, status: "present", offset: off, length: n * f.width, raw, value, display: value.map((v) => displayOf(v, f.unit)).join(", ") });
      if (n === 0) out.errors.push(`${f.name} is present but the value carries none.`);
      off += n * f.width;
      return;
    }
    if (off + f.width > bytes.length) {
      out.errors.push(`${f.name} is present and needs ${f.width} octet${f.width > 1 ? "s" : ""} at offset ${off}; the value has ${bytes.length - off}.`);
      stopped = `the value ends inside ${f.name}`;
      out.fields.push({ ...base, status: "unknown", offset: off });
      return;
    }
    const v = readUint(bytes, off, f.width);
    out.spans.push({ start: off, end: off + f.width, field: i, label: f.name });
    if (f.kind === "bits") {
      flags.set(f.name, v);
      const bits = decodeBits(v, f.bits);
      const reservedSet = (bits ?? []).filter((b) => b.reserved && b.set).map((b) => b.label);
      if (reservedSet.length) out.errors.push(`${f.name}: reserved bit${reservedSet.length > 1 ? "s" : ""} ${reservedSet.join(", ")} set.`);
      out.fields.push({ ...base, status: "present", offset: off, length: f.width, raw: v, value: v, display: `0x${v.toString(16).toUpperCase().padStart(f.width * 2, "0")}`, bits });
    } else if (f.kind === "struct") {
      const children = f.children.map((ch) => {
        let r;
        if (f.packed) r = Math.floor(v / 2 ** ch.bitOffset) % 2 ** ch.bitWidth;
        else r = readUint(bytes, off + ch.bitOffset / 8, ch.bitWidth / 8);
        if (ch.kind === "sint") r = toSigned(r, ch.bitWidth);
        const val = scaled(r, ch.scale);
        return { name: ch.name, anchor: ch.anchor, type: ch.type, raw: r, value: val, unit: ch.unit, scale: ch.scale, display: displayOf(val, ch.unit) };
      });
      out.fields.push({ ...base, status: "present", offset: off, length: f.width, raw: v, children, display: children.map((ch) => `${ch.name} ${ch.display}`).join("; ") });
    } else {
      const raw = f.kind === "sint" ? toSigned(v, f.width * 8) : v;
      const value = scaled(raw, f.scale);
      const row = f.values?.find((r) => raw >= r.from && raw <= r.to) ?? null;
      out.fields.push({
        ...base,
        status: "present",
        offset: off,
        length: f.width,
        raw,
        value,
        display: row ? `${raw} (${row.description})` : displayOf(value, f.unit),
        valueLabel: row ? row.description : null,
      });
    }
    off += f.width;
  });

  if (stopped) {
    out.stopped = stopped;
    if (off < bytes.length) out.spans.push({ start: off, end: bytes.length, field: -1, label: "Not decoded" });
  } else if (off < bytes.length) {
    out.trailing = bytes.length - off;
    out.spans.push({ start: off, end: bytes.length, field: -1, label: "Not described by the structure" });
    out.errors.push(`${out.trailing} octet${out.trailing > 1 ? "s" : ""} left over after the last field the structure describes.`);
  }
  return out;
}

/** One decoded field by name, or null. */
export function fieldOf(decoded, name) {
  return decoded.fields.find((f) => f.name === name) ?? null;
}

/* ---------------------------------------------------------------------- *
 * Encoding (synthetic samples and tests)
 * ---------------------------------------------------------------------- */

/**
 * Build a value from a compiled layout. `values` maps field names to raw
 * (unscaled) numbers, arrays, strings, or {member: raw} objects for structs.
 * Each flags field is set from the presence conditions of the fields given
 * and not given — so the flags are whatever the SIG's structure says they
 * must be — plus `extraBits[flagsName]` for bits that carry no field.
 * Throws when two fields ask one bit to be both 0 and 1.
 */
export function encode(layout, values, extraBits = {}) {
  const assigned = new Map();
  const assign = (field, bit, v, why) => {
    if (!assigned.has(field)) assigned.set(field, new Map());
    const m = assigned.get(field);
    if (m.has(bit) && m.get(bit) !== v) throw new Error(`${field} bit ${bit} is asked to be both 0 and 1 (${why})`);
    m.set(bit, v);
  };
  for (const f of layout.fields) {
    if (!f.presence) continue;
    const want = Object.prototype.hasOwnProperty.call(values, f.name);
    assign(f.presence.field, f.presence.bit, want ? f.presence.value : 1 - f.presence.value, f.name);
  }
  for (const [field, bits] of Object.entries(extraBits)) for (const b of bits) assign(field, b, 1, "extra");

  const out = [];
  for (const f of layout.fields) {
    if (f.kind === "bits") {
      let v = typeof values[f.name] === "number" ? values[f.name] : 0;
      for (const [bit, on] of assigned.get(f.name) ?? []) {
        if (on && !bitOf(v, bit)) v += 2 ** bit;
        else if (!on && bitOf(v, bit)) v -= 2 ** bit;
      }
      writeUint(out, v, f.width);
      continue;
    }
    const given = Object.prototype.hasOwnProperty.call(values, f.name);
    if (f.presence && !given) continue;
    if (!f.presence && !given) {
      if (f.sizeKind === "fixed") throw new Error(`encode: ${f.name} is always present and was not given`);
      continue;
    }
    const v = values[f.name];
    if (f.kind === "uint" || f.kind === "sint") writeUint(out, v, f.width);
    else if (f.kind === "array") for (const x of v) writeUint(out, x, f.width);
    else if (f.kind === "utf8") out.push(...new TextEncoder().encode(v));
    else if (f.kind === "struct") {
      if (f.packed) {
        let acc = 0;
        for (const ch of f.children) acc += (v[ch.name] % 2 ** ch.bitWidth) * 2 ** ch.bitOffset;
        writeUint(out, acc, f.width);
      } else for (const ch of f.children) writeUint(out, v[ch.name], ch.bitWidth / 8);
    } else throw new Error(`encode: ${f.name} (${f.type}) cannot be encoded: ${f.reason}`);
  }
  return Uint8Array.from(out);
}

/* ---------------------------------------------------------------------- *
 * Cumulative revolutions → cadence and speed
 * ---------------------------------------------------------------------- */

/**
 * The step between two readings of a counter that wraps at 2^bits, as a
 * non-negative number. Cumulative revolutions and event times are unsigned
 * fields of fixed width, so a smaller second reading means it wrapped.
 */
export function wrapDelta(prev, cur, bits) {
  const m = 2 ** bits;
  return (((cur - prev) % m) + m) % m;
}

const childOf = (field, re) => field?.children?.find((c) => re.test(c.name)) ?? null;

/**
 * Revolutions per minute and the time between two decoded struct readings of
 * the same Wheel or Crank Revolution Data field. The counter widths come from
 * the members' types and the tick from the event time's own scale, so the
 * CSC wheel (1/1024 s) and the Cycling Power wheel (1/2048 s) are each read
 * as their structure says.
 *
 * rpm is null when the event time did not move (no new revolution event
 * since the last notification) or the revolutions went backwards by more
 * than a wrap could explain.
 */
export function revolutionRate(prevField, curField) {
  const pr = childOf(prevField, /^Cumulative .* Revolutions$/);
  const pt = childOf(prevField, /^Last .* Event Time$/);
  const cr = childOf(curField, /^Cumulative .* Revolutions$/);
  const ct = childOf(curField, /^Last .* Event Time$/);
  if (!pr || !pt || !cr || !ct || !ct.scale) return null;
  const revBits = Number(/(\d+)$/.exec(cr.type)?.[1]);
  const timeBits = Number(/(\d+)$/.exec(ct.type)?.[1]);
  const dRevs = wrapDelta(pr.raw, cr.raw, revBits);
  const dTicks = wrapDelta(pt.raw, ct.raw, timeBits);
  const dt = Number((dTicks * ct.scale.factor).toPrecision(12));
  const tick = ct.scale.factor;
  if (dTicks === 0) return { dRevs, dTicks, dt: 0, tick, rpm: null, reason: dRevs === 0 ? "no new event since the previous notification" : "revolutions moved but the event time did not" };
  return { dRevs, dTicks, dt, tick, rpm: (dRevs / dt) * 60, reason: null };
}

/** Speed in km/h from a wheel revolution rate and a circumference in millimetres. */
export function wheelSpeedKmh(rate, circumferenceMm) {
  if (!rate || rate.rpm == null || !(circumferenceMm > 0)) return null;
  const metresPerSecond = (rate.dRevs * (circumferenceMm / 1000)) / rate.dt;
  return metresPerSecond * 3.6;
}

/** Distance in metres covered by `dRevs` wheel revolutions. */
export function wheelDistanceM(dRevs, circumferenceMm) {
  return (dRevs * circumferenceMm) / 1000;
}
